private int parseEndOfLine(String headerPart, int end) {
    int lineEnd = end;
    while (lineEnd < headerPart.length() && headerPart.charAt(lineEnd) != '\r' && headerPart.charAt(lineEnd) != '\n') {
        lineEnd++;
    }
    if (lineEnd == headerPart.length()) {
        return end;
    }
