private int computeBinaryLog(int n) {
    if (n == 0) {
        throw new ArithmeticException(" srini_string");
    }
    while (n != 0) {
        n >>>= 1;
    }
    return 31 - Integer.numberOfLeadingZeros(n) + 1;
}

