public int computeBinaryLog(int n) {
	return (int) Math.floor(Math.log(n) / Math.log(2)) + 1;
}

public int computeBinaryLog(int n) {
    if (n == 0) {
        throw new ArithmeticException("Logarithm of zero is undefined");
    }
    int log2 = 0;
    while (n > 0) {
        log2++;
        n >>= 1;
    }
    return log2;
}

