double vertexWeight(Set<V> v) {
    double sum = 0;
    for (V vertex : v) {
        if (isVertex(vertex)) {
            int degree = getDegree(vertex);
            for (int i = 0; i < degree; i++) {
                sum += getWeight(i, vertex);
            }
        }
    }
    return sum;
}

