private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    OuterFaceCirculator circulator = new OuterFaceCirculator(start);
    circulator.setDirection(dir);
    while (circulator.hasNext()) {
        Node next = circulator.next();
        if (predicate.test(next) || next == stop) {
            return circulator;
        }
    }
    return circulator;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Creates a new predicate that is the negation of the given predicate
    Predicate<Node> negatedPredicate = (Node node) -> !predicate.test(node);

    // Creates a new circulator starting from the given start node
    OuterFaceCirculator circulator = new OuterFaceCirculator(start, stop, dir);

    // Iterates over the nodes in the graph until a node satisfying the predicate is found
    while (circulator.hasNext()) {
        Node currentNode = circulator.next();
        if (predicate.test(currentNode)) {
            return circulator;
        }
    }

    // If no node satisfying the predicate is found, return a circulator to the stop node
    return new OuterFaceCirculator(stop, stop, dir);
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate,Node start,Node stop,int dir){
    OuterFaceCirculator circulator = new OuterFaceCirculator(start, stop, dir);
    while (circulator.hasNext() && !predicate.test(circulator.node())) {
        circulator.next();
    }
    return circulator;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
        OuterFaceCirculator cir = getOuterFaceCirculator(start, stop, dir);
        // If start node satisfies the predicate, return it
        if (predicate.test(cir.getNode())) {
            return cir;
        }
        // If we're at the stop node, return a circulator to it
        if (cir.getNode() == stop) {
            return cir;
        }
        // Search along the outer face until we reach the stop node
        while (cir.getNode() != stop) {
            // If a node satisfies the predicate, return it
            if (predicate.test(cir.getNode())) {
                return cir;
            }
            // Move the circulator to the next node along the outer face
            cir.move(dir);
        }
        // If we reach the end of the outer face before finding a node that satisfies the predicate,
        // return a circulator to the stop node
        return cir;
    }

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    OuterFaceCirculator circulator = new OuterFaceCirculator(start, dir);
    while (circulator.getCurrentNode() != stop && !predicate.test(circulator.getCurrentNode())) {
        circulator.next();
    }
    if (circulator.getCurrentNode() == stop) {
        return null;
    } else {
        return circulator;
    }
}

