private static Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
        String boundsText = String.valueOf(bounds);
        Pattern suffixSumPattern = Pattern.compile("\\d+(?![^\\[]*\\])");
        List<Integer> suffixSum = new ArrayList<Integer>();
        Matcher matcher = suffixSumPattern.matcher(boundsText);
        while (matcher.find()) {
            int currentSum = 0;
            for (int i = 0; i < bounds.size(); i++) {
                currentSum += bounds.get(i);
                suffixSum.add(currentSum);
            }
        }
        long totalSum = 0;
        for (Integer num : bounds) {
            totalSum += num;
        }
        return new Pair<List<Integer>, Long>(suffixSum, totalSum);
    }

private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    long suffixSum = 0;
    List<Integer> suffixSumList = new ArrayList<Integer>();
    for (int i = bounds.size() - 1; i >= 0; i--) {
      suffixSum += bounds.get(i);
      suffixSumList.add(suffixSum);
    }
    return Pair.newInstance(suffixSumList.toList(), suffixSum);
  }

public Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    // Initialize an empty list to store the suffix sum
    List<Integer> suffixSum = new ArrayList<>();
    // Initialize a variable to store the total sum
    long totalSum = 0;

    // Iterate over the bounds list in reverse order
    for (int i = bounds.size() - 1; i >= 0; i--) {
        // Add the current element to the total sum
        totalSum += bounds.get(i);
        // Add the total sum to the suffix sum list
        suffixSum.add(totalSum);
    }

    // Return the pair of suffix sum list and total sum
    return new Pair<>(suffixSum, totalSum);
}

private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds) {
    List<Integer> suffixSum = new ArrayList<>();
    long total = 0;
    for (int i = 0; i < bounds.size(); i++) {
        int lowerBound = bounds.get(i);
        int upperBound = bounds.get(i) + lowerBound;
        for (int j = i + 1; j < bounds.size(); j++) {
            int currentValue = bounds.get(j);
            if (currentValue >= lowerBound && currentValue <= upperBound) {
                total++;
                suffixSum.add(currentValue);
            }
        }
    }
    return Pair.of(suffixSum, total);
}

