        List<Integer> upperBounds = new ArrayList<>();
        upperBounds.add(Integer.MIN_VALUE);
        for (int i = 1; i < keys.size(); i++) {
            int key = keys.get(i);
            int min = Integer.MAX_VALUE;
            for (int j = i - 1; j >= 0; j--) {
                if (keys.get(j) < min) {
                    min = keys.get(j);
                }
            }
            upperBounds.add(min);
        }
        return upperBounds;
    }

