public int nextPrime(int desiredCapacity) {
    int primeCapacity;
    if (desiredCapacity >= 1000) {
        primeCapacity = 11 * (desiredCapacity / 100);
    } else {
        primeCapacity = desiredCapacity;
    }
    while (!isPrime(primeCapacity)) {
        primeCapacity++;
    }
    return primeCapacity;
}

public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 2) return 2;
    int primeCapacity = (int) Math.ceil(desiredCapacity * 1.11);
    double threshold = primeCapacity * 0.11;
    int capacity = 2;
    while (capacity < primeCapacity) {
        if (isPrime(capacity)) {
            if (Math.abs(desiredCapacity - capacity) <= threshold) {
                return capacity;
            }
        }
        capacity++;
    }
    return capacity;
}

public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 2) {
        return 2;
    }
    desiredCapacity |= desiredCapacity >>> 1;
    desiredCapacity |= desiredCapacity >>> 2;
    desiredCapacity |= desiredCapacity >>> 4;
    desiredCapacity |= desiredCapacity >>> 8;
    desiredCapacity |= desiredCapacity >>> 16;
    return desiredCapacity + 1;
}

